#!/usr/bin/env node
/**
 * Tests for hooks/nudges.js, the single entry point for context-nudge and edit-nudge. Zero
 * dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * The nudges' own rules (bands, the third edit, subagents, scratch files) are covered by their test
 * files; here only the wiring: the right nudges per event, one merged output, the counter reset, and
 * silence on anything else. Each case gets its own CLAUDE_CONFIG_DIR.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const HOOK = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'nudges.js');
const created = [];
process.on('exit', () => {
  for (const dir of created) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

function sandbox() {
  const config = mkdtempSync(join(tmpdir(), 'nudges-'));
  created.push(config);
  mkdirSync(join(config, '.cache'));
  return config;
}

const snapshot = (config, id, used_tokens) => writeFileSync(
  join(config, '.cache', `context-${id}.json`),
  JSON.stringify({ used_tokens, window: 1_000_000, warm: true, at: Date.now() }),
);

/** The hook's `hookSpecificOutput` for one payload, null when it said nothing. */
function fire(config, payload) {
  const r = spawnSync(process.execPath, [HOOK], {
    input: typeof payload === 'string' ? payload : JSON.stringify(payload),
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: '' },
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
}

const prompt = (config, id = 'sess-1') => fire(config, { session_id: id, hook_event_name: 'UserPromptSubmit', prompt: 'x' });
const edit = (config) => fire(config, { session_id: 'sess-1', hook_event_name: 'PostToolUse', tool_name: 'Edit', tool_input: { file_path: 'a.cs' } });

test('UserPromptSubmit: the context nudge speaks once per band', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 210_000);
  const out = prompt(config);
  assert.equal(out.hookEventName, 'UserPromptSubmit');
  assert.match(out.additionalContext, /^Contesto a 210k token/);
  assert.equal(prompt(config), null, 'same band: already said');
});

test('UserPromptSubmit: the edit counter is reset by the same process', () => {
  const config = sandbox();
  edit(config);
  edit(config);
  assert.ok(existsSync(join(config, '.cache', 'edits-sess-1.json')));
  assert.equal(prompt(config), null);
  assert.ok(!existsSync(join(config, '.cache', 'edits-sess-1.json')));
});

test('PostToolUse: the third edit nudges towards the implementer, never the context line', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 330_000);
  assert.equal(edit(config), null);
  assert.equal(edit(config), null);
  const third = edit(config);
  assert.equal(third.hookEventName, 'PostToolUse');
  assert.match(third.additionalContext, /\bimplementer\b/);
  assert.doesNotMatch(third.additionalContext, /Contesto/);
});

test('an unknown event, a bad payload or an empty one → silent, exit 0', () => {
  const config = sandbox();
  snapshot(config, 'sess-1', 330_000);
  assert.equal(fire(config, { session_id: 'sess-1', hook_event_name: 'Stop' }), null);
  assert.equal(fire(config, 'not json'), null);
  assert.equal(fire(config, ''), null);
});

/** The pattern an older settings.json wires: `node -e "require(<hook>)"`, where `require.main` is undefined. */
function viaRequire(config, hook, payload) {
  const file = join(dirname(HOOK), hook);
  const r = spawnSync(process.execPath, ['-e', `try{require(${JSON.stringify(file)})}catch{process.exit(0)}`], {
    input: JSON.stringify(payload),
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_CONFIG_DIR: config, CLAUDE_NUDGE_STEPS: '' },
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput : null;
}

test('an older settings.json that requires a nudge directly still gets its output', () => {
  const config = sandbox();
  const edit = { session_id: 'sess-1', hook_event_name: 'PostToolUse', tool_name: 'Edit', tool_input: { file_path: 'a.cs' } };
  assert.equal(viaRequire(config, 'edit-nudge.js', edit), null);
  assert.equal(viaRequire(config, 'edit-nudge.js', edit), null);
  assert.match(viaRequire(config, 'edit-nudge.js', edit).additionalContext, /\bimplementer\b/);
  snapshot(config, 'sess-2', 210_000);
  const out = viaRequire(config, 'context-nudge.js', { session_id: 'sess-2', hook_event_name: 'UserPromptSubmit', prompt: 'x' });
  assert.match(out.additionalContext, /^Contesto a 210k token/);
});
